package org.apache.commons.math.optimization.general;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxEvaluationsExceededException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.exception.LocalizedFormats;
import org.apache.commons.math.linear.InvalidMatrixException;
import org.apache.commons.math.linear.LUDecompositionImpl;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.optimization.DifferentiableMultivariateVectorialOptimizer;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.SimpleVectorialValueChecker;
import org.apache.commons.math.optimization.VectorialConvergenceChecker;
import org.apache.commons.math.optimization.VectorialPointValuePair;
import org.apache.commons.math3.exception.FunctionEvaluationException;
import org.apache.commons.math3.optimization.datapoint.OptimizationException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for AbstractLeastSquaresOptimizer#guessParametersErrors.
 * Since the class is abstract and the method depends on internal state (rows, cols, chiSquare, covariances),
 * we use a concrete subclass and reflection to simulate the state.
 */
public class AbstractLeastSquaresOptimizer_guessParametersErrors_TriageGen2Test {

    private TestOptimizer optimizer;

    // Concrete implementation for testing purposes
    private static class TestOptimizer extends AbstractLeastSquaresOptimizer {
        private int rows;
        private int cols;
        private double chiSquare;
        private double[][] covariances;

        protected TestOptimizer(int rows, int cols, double chiSquare, double[][] covariances) {
            this.rows = rows;
            this.cols = cols;
            this.chiSquare = chiSquare;
            this.covariances = covariances;
        }

        @Override
        protected VectorialPointValuePair doOptimize() {
            return null;
        }

        // Mocking the protected/public methods used by guessParametersErrors
        @Override
        public double getChiSquare() {
            return chiSquare;
        }

        @Override
        public double[][] getCovariances() throws FunctionEvaluationException, OptimizationException {
            return covariances;
        }

        // Helper to set the protected fields via reflection if needed, 
        // but here we use local fields and assume the method under test 
        // accesses them via getters or direct field access.
        // Since we are testing the logic of the method, we must ensure 
        // the fields 'rows' and 'cols' in the parent class are accessible or simulated.
    }

    @Before
    public void setUp() throws Exception {
        // We will initialize the optimizer in individual tests to control state.
    }

    /**
     * Tests that an OptimizationException is thrown when rows <= cols.
     * This covers the first branch of the if-statement.
     */
    @Test(expected = OptimizationException.class)
    public void testGuessParametersErrorsThrowsExceptionWhenRowsLessOrEqualToCols() throws Exception {
        // We need to inject rows and cols into the parent class via reflection
        TestOptimizer optimizer = new TestOptimizer(5, 5, 10.0, new double[5][5]);
        setInternalState(optimizer, "rows", 5);
        setInternalState(optimizer, "cols", 5);

        optimizer.guessParametersErrors();
    }

    /**
     * Tests the successful calculation of parameter errors.
     * Formula: errors[i] = sqrt(covar[i][i]) * sqrt(chiSquare / (rows - cols))
     */
    @Test
    public void testGuessParametersErrorsSuccess() throws Exception {
        int rows = 10;
        int cols = 3;
        double chiSquare = 12.0;
        // degrees of freedom = 10 - 3 = 7
        // c = sqrt(12 / 7)
        double c = Math.sqrt(chiSquare / (rows - cols));

        double[][] covar = {
            {4.0, 0.0, 0.0}, // sqrt(4.0) = 2.0
            {0.0, 9.0, 0.0}, // sqrt(9.0) = 3.0
            {0.0, 0.0, 1.0}  // sqrt(1.0) = 1.0
        };

        TestOptimizer optimizer = new TestOptimizer(rows, cols, chiSquare, covar);
        setInternalState(optimizer, "rows", rows);
        setInternalState(optimizer, "cols", cols);

        double[] expectedErrors = new double[] {
            2.0 * c,
            3.0 * c,
            1.0 * c
        };

        double[] actualErrors = optimizer.guessParametersErrors();

        Assert.assertArrayEquals(expectedErrors, actualErrors, 1e-10);
    }

    /**
     * Tests the case where the error is zero.
     */
    @Test
    public void testGuessParametersErrorsWithZeroChiSquare() throws Exception {
        int rows = 5;
        int cols = 2;
        double chiSquare = 0.0;
        double[][] covar = {
            {1.0, 0.0},
            {0.0, 1.0}
        };

        TestOptimizer optimizer = new TestOptimizer(rows, cols, chiSquare, covar);
        setInternalState(optimizer, "rows", rows);
        setInternalState(optimizer, "cols", cols);

        double[] actualErrors = optimizer.guessParametersErrors();

        Assert.assertEquals(0.0, actualErrors[0], 1e-10);
        Assert.assertEquals(0.0, actualErrors[1], 1e-10);
    }

    /**
     * Helper method to set private/protected fields in the Abstract class via reflection.
     */
    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        Field field = AbstractLeastSquaresOptimizer.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
